<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><dl><dt>Student ID</dt><dd><?= esc($request['student_id']) ?></dd><dt>Name</dt><dd><?= esc($request['full_name']) ?></dd><dt>Contact email</dt><dd><?= esc($request['contact_email']) ?></dd><dt>Program</dt><dd><?= esc($request['program']) ?></dd><dt>Explanation</dt><dd><?= esc($request['explanation']) ?></dd><dt>Document</dt><dd><a href="<?= site_url('admin/verification-requests/'.$request['id'].'/document') ?>">Download <?= esc($request['document_name']) ?></a></dd><dt>Matching student record</dt><dd><?= $student?'<a href="'.site_url('admin/students/'.$student['id']).'">'.esc($student['full_name']).'</a>':'None found' ?></dd></dl><form method="post" action="<?= site_url('admin/verification-requests/'.$request['id']) ?>"><?= csrf_field() ?><label>Status<select name="status"><?php foreach(['pending','under_review','resolved','rejected'] as $s):?><option <?= $request['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select></label><label>Internal review notes<textarea name="review_notes" rows="5" maxlength="4000"><?= esc($request['review_notes']??'') ?></textarea></label><button>Save review</button></form><h2>Audit history</h2><ul><?php foreach($audits as $a):?><li><?= esc($a['created_at']) ?> — <?= esc($a['action']) ?><?= $a['notes']?' — '.esc($a['notes']):'' ?></li><?php endforeach ?></ul><?= $this->endSection() ?>
